protected boolean isOrderHoldApplicable()
{
    boolean holdApplies = next isOrderHoldApplicable();
    holdApplies = this.METisOrderHoldApplicable();
    return holdApplies;
}

protected boolean METisOrderHoldApplicable()
{
    boolean holdApplies;

    initOrderHoldControlItems = new Set(Types::Container);

    Array allOrderHoldChecks = METCredManOrderHoldCheckFactory::getAllOrderHoldChecks();
    int instanceCount = allOrderHoldChecks.lastIndex();

    for (int instanceIdx = 1; instanceIdx <= instanceCount; instanceIdx++)
    {
        CredManIOrderHoldCheck orderHoldCheck = allOrderHoldChecks.value(instanceIdx);
        CredManOrderHoldCheckContract credManOrderHoldCheckContract = this.getOrderHoldCheckContract();
        credManOrderHoldCheckContract.documentStatusCheck = CredManDocumentStatusCheck::METCreditCheck;
       // credManOrderHoldCheckContract
        orderHoldCheck.setOrderHoldCheckContract(credManOrderHoldCheckContract);

        if (orderHoldCheck.isApplicable())
        {
            Set orderHoldControlSubSet = orderHoldCheck.getOrderHoldControlItems();

            initOrderHoldControlItems = Set::union(initOrderHoldControlItems, orderHoldControlSubSet);

            holdApplies = true;
        }
    }

    return holdApplies;
}
